// HasBotIDRef applies the HasEdge predicate on the "bot_id_ref" edge.
func HasBotIDRef() predicate.ScopePolicy {
	return predicate.ScopePolicy(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, BotIDRefTable, BotIDRefColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBotIDRefWith applies the HasEdge predicate on the "bot_id_ref" edge with a given conditions (other predicates).
func HasBotIDRefWith(preds ...predicate.BotAccount) predicate.ScopePolicy {
	return predicate.ScopePolicy(func(s *sql.Selector) {
		step := newBotIDRefStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ScopePolicy) predicate.ScopePolicy {
	return predicate.ScopePolicy(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ScopePolicy) predicate.ScopePolicy {
	return predicate.ScopePolicy(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ScopePolicy) predicate.ScopePolicy {
	return predicate.ScopePolicy(sql.NotPredicates(p))
}
